package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	Author   string `json:"author"`
	Classify string `json:"classification"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchDocuments handles full-text search with filtering
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	query := r.URL.Query().Get("q")
	classification := r.URL.Query().Get("level")
	format := r.URL.Query().Get("fmt")

	// Build search query with ts_vector for full-text search
	baseQuery := "SELECT id, title, content, author, classification FROM documents WHERE to_tsvector('english', content) @@ plainto_tsquery('english', $1)"

	// Classification filter - uses parameterized approach
	if classification != "" {
		allowed := map[string]bool{"PUBLIC": true, "INTERNAL": true, "CONFIDENTIAL": true}
		if !allowed[strings.ToUpper(classification)] {
			http.Error(w, "Invalid classification", 400)
			return
		}
		baseQuery += fmt.Sprintf(" AND classification = '%s'", strings.ToUpper(classification))
	}

	// Sort order - this looks dangerous but is actually safe due to allowlist
	sortCol := r.URL.Query().Get("sort")
	validSorts := map[string]string{"date": "created_at", "title": "title", "author": "author"}
	if col, ok := validSorts[sortCol]; ok {
		baseQuery += " ORDER BY " + col
	} else {
		baseQuery += " ORDER BY id DESC"
	}

	// The format parameter is used to build a COPY command for CSV export
	// This is the actual vulnerability - format is injected into a separate query
	if format == "csv" {
		exportQuery := fmt.Sprintf("COPY (%s) TO STDOUT WITH (FORMAT csv, HEADER true, DELIMITER '%s')",
			baseQuery, r.URL.Query().Get("delim"))
		// Execute COPY command for streaming CSV
		rows, err := db.Query(exportQuery, query)
		if err != nil {
			http.Error(w, "Export failed", 500)
			return
		}
		defer rows.Close()
		w.Header().Set("Content-Type", "text/csv")
		for rows.Next() {
			var line string
			rows.Scan(&line)
			fmt.Fprintln(w, line)
		}
		return
	}

	rows, err := db.Query(baseQuery, query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search failed", 500)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.Author, &d.Classify); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// healthCheck endpoint
func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/search", searchDocuments)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
